package ru.voicerooms;import static org.junit.Assert.*;import org.junit.Test;public class TrustedOriginTest {  @Test  public void acceptsOnlyTheApplicationHttpsOrigin() {    assertTrue(TrustedOrigin.isTrusted("https://voise.24projects.ru/?room=ROOM#key=secret"));    assertTrue(TrustedOrigin.isTrusted("https://voise.24projects.ru:443/"));    for (String s :        new String[] {          "http://voise.24projects.ru/",          "https://voise.24projects.ru.evil.test/",          "https://evil.test@voise.24projects.ru/",          "https://voise.24projects.ru:444/",          "file:///data/local/a",          "javascript:alert(1)",          "https://evil.test"        }) assertFalse(s, TrustedOrigin.isTrusted(s));  }}